/**
 * Fix two before/after pairs generated by a prior pass:
 * - Pair 2 (woman, crown): before/after were nearly indistinguishable — regenerate
 *   the "after" with an unambiguous, visible density increase.
 * - Pair 3 (man, temple): showed ear/cheek/jaw — not actually faceless despite the
 *   intent. Regenerate both frames cropped tighter to hair/scalp only.
 *
 * Usage: GEMINI_API_KEY=xxx node generate-ba-fixes.js
 */

const fs = require('fs');
const path = require('path');

const apiKey = process.env.GEMINI_API_KEY;
if (!apiKey) {
  console.error('❌ Missing GEMINI_API_KEY.');
  process.exit(1);
}

const MODEL = 'gemini-3.1-flash-image';
const HL_DIR = path.join(__dirname, 'public', 'assets', 'hl');

async function generate(promptText, refPaths, outPath) {
  const input = [{ type: 'text', text: promptText }];
  for (const p of refPaths) {
    input.push({ type: 'image', mime_type: 'image/png', data: fs.readFileSync(p).toString('base64') });
  }
  const response = await fetch('https://generativelanguage.googleapis.com/v1beta/interactions', {
    method: 'POST',
    headers: { 'x-goog-api-key': apiKey, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: MODEL, input }),
  });
  const data = await response.json();
  let imageB64 = data.output_image?.data || null;
  if (!imageB64 && Array.isArray(data.steps)) {
    for (const step of data.steps) {
      const block = (step.content || []).find((c) => c.type === 'image');
      if (block) { imageB64 = block.data; break; }
    }
  }
  if (!imageB64) {
    console.error('❌ No image in response:', JSON.stringify(data, null, 2).slice(0, 2000));
    return false;
  }
  fs.writeFileSync(outPath, Buffer.from(imageB64, 'base64'));
  console.log(`✅ Saved: ${path.relative(__dirname, outPath)}`);
  return true;
}

async function run() {
  // Pair 2 fix: regenerate "after" with an unmistakable, visible improvement —
  // using before-2.png as the reference so hair color/angle/bun stay identical.
  await generate(
    `This is a "before" photo (back of head, crown parting line, hair in a low
bun, no face visible). Generate the matching "after treatment" version: same
person, same angle, same hairstyle/bun, same lighting and plain background —
but with a CLEARLY, UNMISTAKABLY denser crown. The parting line should show
significantly less visible scalp than the reference — thicker, fuller
coverage, an obvious visible improvement at a glance, not a subtle one. Same
photographic style as the reference (plain light background, no face, realistic).`,
    [path.join(HL_DIR, 'before-2.png')],
    path.join(HL_DIR, 'after-2.png')
  );

  // Pair 3 fix: regenerate BOTH frames, cropped tighter to exclude ear/cheek/jaw
  // — hair and scalp only, no recognizable facial features.
  await generate(
    `A close-up photo of a man's temple/hairline area showing a receding
hairline with visible thinning — cropped TIGHTLY to show ONLY hair, hairline,
and scalp. Do NOT include the ear, cheek, jaw, or any facial skin below the
hairline — frame it so no facial feature is recognizable, purely a hair/scalp
texture study. Plain light gray/white studio background, soft even lighting,
photorealistic, high detail on individual hair strands.`,
    [],
    path.join(HL_DIR, 'before-3.png')
  );
  await generate(
    `This is a "before" photo of a man's temple/hairline (hair and scalp only,
no ear, no cheek, no jaw, no facial features — tightly cropped to hair
texture). Generate the matching "after treatment" version: same crop, same
angle, same lighting, same plain background — but with CLEARLY denser hair
coverage at the hairline, an obvious visible improvement, still with no ear,
cheek, jaw, or facial skin in frame.`,
    [path.join(HL_DIR, 'before-3.png')],
    path.join(HL_DIR, 'after-3.png')
  );
}

run().catch((err) => { console.error('❌ Failed:', err.message); process.exit(1); });
